static void fail(const QString &s){throw std::runtime_error(s.toUtf8().constData());}
struct Allocator{struct Header{size_t bytes;void *padding[3];};ISzAlloc api;size_t live=0;Allocator(){api.Alloc=&allocate;api.Free=&release;}static void *allocate(ISzAllocPtr ptr,size_t bytes){Allocator *self=reinterpret_cast<Allocator*>(const_cast<ISzAlloc*>(ptr));const size_t cap=512u*1024u*1024u;if(bytes>cap || self->live>cap-bytes)return 0;Header *memory=static_cast<Header*>(std::malloc(bytes+sizeof(Header)));if(!memory)return 0;memory->bytes=bytes;self->live+=bytes;return memory+1;}static void release(ISzAllocPtr ptr,void *value){if(!value)return;Allocator *self=reinterpret_cast<Allocator*>(const_cast<ISzAlloc*>(ptr));Header *memory=static_cast<Header*>(value)-1;self->live-=memory->bytes;std::free(memory);}};
struct Input{ISeekInStream api;QFile file;const std::atomic<bool> *stop;Input(const QString &path,const std::atomic<bool>&cancel):file(path),stop(&cancel){api.Read=&read;api.Seek=&seek;if(!file.open(QIODevice::ReadOnly))fail(QStringLiteral("Cannot read selected archive."));}static SRes read(ISeekInStreamPtr ptr,void *data,size_t *size){Input *self=reinterpret_cast<Input*>(const_cast<ISeekInStream*>(ptr));if(self->stop->load()){*size=0;return SZ_ERROR_PROGRESS;}const qint64 amount=self->file.read(static_cast<char*>(data),qMin<qint64>(*size,1024*1024));if(amount<0){*size=0;return SZ_ERROR_READ;}*size=static_cast<size_t>(amount);return SZ_OK;}static SRes seek(ISeekInStreamPtr ptr,Int64 *position,ESzSeek origin){Input *self=reinterpret_cast<Input*>(const_cast<ISeekInStream*>(ptr));qint64 target=*position;if(origin==SZ_SEEK_CUR)target+=self->file.pos();else if(origin==SZ_SEEK_END)target+=self->file.size();if(target<0 || target>self->file.size() || !self->file.seek(target))return SZ_ERROR_READ;*position=target;return SZ_OK;}};
struct Archive{CSzArEx value;Allocator alloc;Byte *output=0;CLookToRead2 look;std::vector<Byte> input;Archive(Input &source):input(256*1024){SzArEx_Init(&value);LookToRead2_CreateVTable(&look,False);look.buf=input.data();look.bufSize=input.size();look.realStream=&source.api;LookToRead2_INIT(&look);CrcGenerateTable();const SRes result=SzArEx_Open(&value,&look.vt,&alloc.api,&alloc.api);if(result!=SZ_OK){SzArEx_Free(&value,&alloc.api);fail(QStringLiteral("Cannot decode selected 7z archive (error %1).").arg(result));}}~Archive(){if(output)alloc.api.Free(&alloc.api,output);SzArEx_Free(&value,&alloc.api);}};
void extractDirectory(const QString &path,const QString &directory,const QString &destination,const std::atomic<bool> &stop){
 if(!safeRelative(directory))fail(QStringLiteral("Unsafe driver folder in the catalog."));QDir output(destination);if(!output.exists() || !output.entryList(QDir::NoDotAndDotDot|QDir::AllEntries|QDir::Hidden|QDir::System).isEmpty())fail(QStringLiteral("Extraction requires a new empty private directory."));
 const QString prefix=QDir::fromNativeSeparators(directory)+QLatin1Char('/'),base=QFileInfo(destination).canonicalFilePath()+QLatin1Char('/');Input input(path,stop);Archive archive(input);if(archive.value.NumFiles>200000)fail(QStringLiteral("Archive contains too many files."));QVector<QPair<UInt32,QString>> chosen;QSet<QString> names;qint64 total=0;
 for(UInt32 i=0;i<archive.value.NumFiles;++i){const size_t size=SzArEx_GetFileNameUtf16(&archive.value,i,0);if(!size || size>2049)fail(QStringLiteral("Unsafe archive filename."));std::vector<UInt16> text(size);SzArEx_GetFileNameUtf16(&archive.value,i,text.data());const QString name=QString::fromUtf16(text.data(),static_cast<int>(size-1));if(!safeRelative(name))fail(QStringLiteral("Archive contains an unsafe path."));if(!name.startsWith(prefix,Qt::CaseInsensitive) || SzArEx_IsDir(&archive.value,i))continue;const QString relative=name.mid(prefix.size());if(!safeRelative(relative) || names.contains(relative.toLower()))fail(QStringLiteral("Ambiguous archive output path."));names.insert(relative.toLower());const UInt64 bytes=SzArEx_GetFileSize(&archive.value,i);if(bytes>2ull*1024*1024*1024 || total>8ll*1024*1024*1024-static_cast<qint64>(bytes))fail(QStringLiteral("Selected driver exceeds extraction limits."));total+=bytes;chosen.append(qMakePair(i,relative));}
 if(chosen.isEmpty())fail(QStringLiteral("Selected driver folder is absent from the archive."));const QStorageInfo storage(destination);if(storage.isValid() && storage.bytesAvailable()>=0 && total+64*1024*1024>storage.bytesAvailable())fail(QStringLiteral("Insufficient free space for the selected driver."));UInt32 block=0xFFFFFFFF;size_t outputSize=0;
 for(const auto &entry:chosen){if(stop.load())fail(QStringLiteral("Extraction cancelled before installation."));size_t offset=0,processed=0;const SRes result=SzArEx_Extract(&archive.value,&archive.look.vt,entry.first,&block,&archive.output,&outputSize,&offset,&processed,&archive.alloc.api,&archive.alloc.api);if(result!=SZ_OK)fail(QStringLiteral("Driver extraction failed (7z error %1); nothing was installed.").arg(result));const QString file=QDir(destination).filePath(entry.second);if(!QDir().mkpath(QFileInfo(file).absolutePath()))fail(QStringLiteral("Cannot create private driver output."));const QString parent=QFileInfo(QFileInfo(file).absolutePath()).canonicalFilePath()+QLatin1Char('/');if(!parent.startsWith(base,Qt::CaseInsensitive))fail(QStringLiteral("Driver output escaped its private directory."));QSaveFile target(file);if(!target.open(QIODevice::WriteOnly))fail(QStringLiteral("Cannot create extracted driver file."));size_t written=0;while(written<processed){const qint64 amount=qMin<qint64>(1024*1024,processed-written);if(target.write(reinterpret_cast<const char*>(archive.output+offset+written),amount)!=amount)fail(QStringLiteral("Cannot save extracted driver file."));written+=amount;}if(!target.commit())fail(QStringLiteral("Cannot commit extracted driver file."));}
}
